  const totalAssets = useMemo(() =>
    form.cashSavings + form.taxableInvestments + form.realEstateEquity +
    form.iraBalance + form.rothBalance + form.k401Balance +
    form.lifeInsuranceCv + form.annuityValue, [form]);
