                  <div className="text-left hidden sm:block">
                    <div className="text-xs font-medium">{s.title}</div>
                  </div>
                </button>
                {i < STEPS.length - 1 && <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0" />}
              </div>
