        {/* Step 4: Risk Assessment */}
        {step === 3 && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2"><Shield className="w-5 h-5 text-blue-400" /> Risk Assessment</CardTitle>
