                      <div className="flex items-center gap-2 mb-1">
                        <Badge variant="outline" className="text-[9px] px-1.5 py-0 border-amber-500/30 text-amber-400">
                          {c.tag}
                        </Badge>
                      </div>
                      <p className="text-[11px] text-slate-300 leading-relaxed">{c.prompt}</p>
