            </div>
          )}

          {/* Navigate button */}
          <div className="flex justify-end pt-4 border-t border-[#12233e]">
            <button
              onClick={(e) => { e.stopPropagation(); navigate(tab.path); }}
              className="rc-btn rc-btn-ghost"
            >
              Open {tab.name} →
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

