    if (sortBy === "score") {
      tabs = [...tabs].sort((a, b) => computeAverage(b.ratings) - computeAverage(a.ratings));
    } else if (sortBy === "importance") {
      tabs = [...tabs].sort((a, b) => b.ratings.importance - a.ratings.importance);
    } else {
      tabs = [...tabs].sort((a, b) => a.name.localeCompare(b.name));
