  return (
    <AppShell>
      {showAdd && <AddClientModal onClose={() => setShowAdd(false)} onSuccess={() => utils.clients.list.invalidate()} />}
      {showImport && <CSVImportModal onClose={() => setShowImport(false)} onSuccess={() => utils.clients.list.invalidate()} />}
