                if (Math.abs(d) < 100) return null;
                return d > 0
                  ? <span className="text-[#22c55e] text-xs ml-1">▲ +{fmt(d)}</span>
                  : <span className="text-rose-400 text-xs ml-1">▼ {fmt(d)}</span>;
