      setIsExporting(true);
      const headers = ["Carrier", "Specialty", "Overall Score", "COMDEX", "AM Best", "S&P", "Moody's", "Fitch", "Total Assets"];
      const rows = filteredCarriers.map((c) => [
        `"${c.carrierName}"`,
        `"${c.specialty}"`,
