    toast.success("Building income timeline...", {
      description: "Analyzing all income streams and tax implications."
    });
  }, [calcMut, currentAge, retirementAge, endAge, targetIncome, inflationRate, coloredSources]);

  useEffect(() => {
    runCalc();
