                      <Button variant="ghost" size="sm" onClick={clearFilters} className="h-6 text-xs text-[#7a95b8] hover:text-white">Clear All</Button>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
