    if (c.email) setEmailTo(c.email);
  }, [selectedClientId, clients.length]);

  const clientName = selectedClient?.name || "Client";

  const handleSaveScenario = () => {
    if (!selectedClientId) {
      toast.error("Select a client before saving a scenario.");
