                    <td className="px-4 py-3 text-right text-[#c8d8ec]">{s.parRate}</td>
                    <td className="px-4 py-3 text-right text-white">{s.avgAnnual}%</td>
                    <td className="px-4 py-3 text-right font-mono text-red-400">{s.worst}%</td>
