                  <tr key={p.year} className="hover:bg-[#1a2f4c]/50 transition-colors">
                    <td className="px-4 py-3 font-medium text-white">{p.year}</td>
                    <td className="px-4 py-3 text-right text-[#c8d8ec]">{fmt(p.accumulated)}</td>
