              <Tooltip contentStyle={{ backgroundColor: '#0d1a2e', borderColor: '#12233e', color: '#fff' }} />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* Chart 5: RadarChart */}
        <div className="rc-card h-72">
          <h3 className="text-lg font-semibold text-white mb-4">Radar Chart: Product Features</h3>
