  const annualIncome = useMemo(() => Math.round(investmentAmount * (annualReturn / 100)), [investmentAmount, annualReturn]);
  const totalIncomeOverLockup = useMemo(() => annualIncome * lockupYears, [annualIncome, lockupYears]);

