      });
    }
    return data;
  }, [showBeneficiary, lockupYears, annualIncome, investmentAmount]);

  const effectiveRateWithout = calcEffectiveRate(taxableIncome, brackets);
  const effectiveRateWith = calcEffectiveRate(taxableAfterDeduction, brackets);

  return (
