              <CardContent className="p-0">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Carrier</TableHead>
                      <TableHead>Index Return</TableHead>
                      <TableHead>Participation/Cap</TableHead>
                      <TableHead className="text-right">Net Credited Rate</TableHead>
