  const fmt = (n: number) => `$${n.toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
  const fmtPct = (n: number) => `${n.toFixed(1)}%`;

  const scoreColor = (score: number) =>
    score >= 80 ? "text-[#22c55e]" : score >= 60 ? "text-[#f0c040]" : "text-red-400";

