  const taxDragData = useMemo(() => {
    if (!result || !result.ladder) return [];

    return result.ladder.map((row: any, i: number) => ({
      year: row.year,
      taxPaid: row.taxEstimate,
      taxSaved: row.taxEstimate * 1.5, // Mock future tax savings
