              <th key={i} className={`p-3 font-medium ${i > 0 ? 'text-right' : ''}`}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody className="text-[#c8d8ec]">
          {data.map((row, i) => renderRow(row, i))}
        </tbody>
      </table>
    </div>
  );

  return (
    <AppShell>
      <div className="space-y-6 max-w-7xl mx-auto pb-12">

