                      </Card>
                    )}
                  </div>
                )}

                {/* Tab Content: Docs */}
                {activeTab === "docs" && (
                  <div className="space-y-6 animate-in fade-in duration-300">
                    <Card>
                      <CardHeader title="Knowledge Base Grounding" icon={BookOpen} />
