                  />
                </div>
              </div>
            </div>

            <div className="p-6 border-t border-[#12233e] bg-[#0a1424] flex gap-3 justify-end">
              <button
                onClick={() => setShowCreate(false)}
                className="px-4 py-2 text-[#c8d8ec] hover:text-white transition-colors font-medium"
