      taxableIncome,
      totalDeductions,
      isItemizing,
      itemizedDeductions,
      standardDeduction,
      withRoth,
      withoutRoth,
      rothTaxCost,
      stateTax,
      totalTaxLiability,
      equivalentTaxableNeeded,
      iulTaxSavings,
      projectionData,
      taxBreakdownData,
      radarData,
      totalIncome
    };
  }, [
