                      { label: "Additional Cost", value: fmt(analysis.rothImpact) },
                      { label: "IUL Annual Savings", value: fmt(analysis.iulSavings) },
                      { label: `${projectionYears}-Year Savings`, value: fmt(analysis.projectedSavings) }
                    ]
                  }
