                  const rothCost = (rothBrk.partBSurcharge + (includePartD ? rothBrk.partDSurcharge : 0)) * mult;
                  const iulCost = (iulBrk.partBSurcharge + (includePartD ? iulBrk.partDSurcharge : 0)) * mult;

