                        <p className="text-2xl font-bold text-emerald-400">{fmt(totalIulSavings)}</p>
                        <p className="text-xs text-[#7a95b8]">IUL IRMAA Savings</p>
                      </div>
                    </div>

                    {/* Chart: Year-by-Year IRMAA Surcharge Comparison */}
