      setSortField(field);
      setSortDirection("asc");
    }
  }, [sortField]);

  const toggleSelectRule = useCallback((id: string) => {
    setSelectedRules(prev => prev.includes(id) ? prev.filter((p) => p !== id) : [...prev, id]);
