          content: editContent,
          version: doc.version + 1,
          generatedAt: new Date().toISOString()
        };

        setDocumentVersions(v => ({
          ...v,
          [editingDocId]: [...(v[editingDocId] || []), updatedDoc]
        }));

        return updatedDoc;
      }
      return doc;
    }));

