                                    </td>
                                    <td className="py-2 text-right text-white font-medium">{fmt(d.value)}</td>
                                    <td className={`py-2 text-right text-xs ${diff > 0 ? 'text-green-400' : diff < 0 ? 'text-red-400' : 'text-[#7a95b8]'}`}>
