                        </div>
                      </div>
                    </div>
                  </TabsContent>
                </div>
              </Tabs>
            </Card>
          </div>
        </div>
      </div>
      <PageInsights pageId="market-scenario-stress-test" />

        <ComplianceFooter pageName="MarketScenarioStressTest" showsTax showsEstate showsProjections showsHistoricalData />
      </AppShell>
  );
}

