              {/* Summary cards */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {summaries.map((s, i) => {
                  const slotIdx = comparisonSlots.findIndex(sl => sl.id === s.slotId);
                  const color = SLOT_COLORS[slotIdx] ?? SLOT_COLORS[0];
