      return {
        delay: delay === 0 ? "Today" : `${delay}yr delay`,
        shielded: Math.round(shielded),
        loss: Math.round(loss),
        saved: Math.round(netWorth * (spousalSplitPct / 100) + attorneyFees + annualIncome * (alimonyPct / 100) * alimonyYears - loss),
      };
    });
