import { useState } from "react";
import { AppShell } from "@/components/AppShell";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Heart, Eye, Crown, Plus, Users, Trophy, EyeOff } from "lucide-react";
import { GENOME, GlowCard, GenomeBackdrop, SectionLabel, fmt$ } from "./_genome/GenomeKit";

const CATEGORIES = [
  { id: "all", label: "All" },
  { id: "iul_strategy", label: "IUL Strategy" },
  { id: "roth_conversion", label: "Roth Conversion" },
  { id: "tax_savings", label: "Tax Savings" },
  { id: "estate_planning", label: "Estate Planning" },
];
const CAT_COLOR = {
  iul_strategy: GENOME.accent, roth_conversion: GENOME.cyan, tax_savings: "#f5b14c", estate_planning: "#34d399",
};
const SEED = [
  { id: 1, author: "Dr. M. · Cardiology", anon: false, cat: "iul_strategy", title: "Overfunded into Pacific Life — first tax-free loan year", body: "Started distributions at year 22. The audit log gave my CPA total confidence.", dollarImpact: 1_240_000, likes: 84, views: 612 },
  { id: 2, author: "Anonymous Physician", anon: true, cat: "roth_conversion", title: "Bracket-filling Roth ladder over 6 years", body: "Buddy kept me honest about the long game. Converted in the low-IRMAA window.", dollarImpact: 410_000, likes: 57, views: 388 },
  { id: 3, author: "Dr. R. · Anesthesiology", anon: false, cat: "estate_planning", title: "Drafted The Legacy with my kids in the room", body: "Spiritual tone. Hardest, best hour of the year. The reflection prompt undid me.", dollarImpact: 0, likes: 132, views: 904 },
  { id: 4, author: "Dr. K. · Surgery", anon: false, cat: "tax_savings", title: "HELOC cycling + solar credits stacked", body: "Three cycles into IUL on The Map. Watched the 30-yr curve bend.", dollarImpact: 286_000, likes: 41, views: 270 },
];
const LEADERS = [
  { name: "Dr. R.", xp: 9820, rep: 92, tier: "crown" },
  { name: "Dr. M.", xp: 8640, rep: 81, tier: "crown" },
  { name: "You", xp: 2480, rep: 81, tier: "crown", me: true },
  { name: "Dr. K.", xp: 2210, rep: 64, tier: "neutral" },
  { name: "Dr. P.", xp: 980, rep: 44, tier: "blackeye" },
];

export default function TheBrotherhood() {
  const [cat, setCat] = useState("all");
  const [stories, setStories] = useState(SEED);
  const [composing, setComposing] = useState(false);
  const [draft, setDraft] = useState({ title: "", body: "", cat: "iul_strategy", anon: false });

  const like = (id) => setStories((s) => s.map((x) => (x.id === id ? { ...x, likes: x.likes + (x.liked ? -1 : 1), liked: !x.liked } : x)));
  const visible = cat === "all" ? stories : stories.filter((s) => s.cat === cat);

  const post = () => {
    if (!draft.title.trim()) return;
    setStories([{ id: Date.now(), author: draft.anon ? "Anonymous Physician" : "You", anon: draft.anon, cat: draft.cat, title: draft.title, body: draft.body, dollarImpact: 0, likes: 0, views: 0 }, ...stories]);
    setDraft({ title: "", body: "", cat: "iul_strategy", anon: false });
    setComposing(false);
  };

  return (
    <AppShell title="The Brotherhood" subtitle="Physician to physician — proof, not promises">
      <div className="relative mx-auto grid max-w-6xl gap-6 lg:grid-cols-[1fr_320px]">
        <GenomeBackdrop />

        {/* Feed */}
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            <div className="flex flex-wrap gap-2">
              {CATEGORIES.map((c) => (
                <button key={c.id} onClick={() => setCat(c.id)}
                  className={`rounded-full px-3.5 py-1.5 text-xs transition-colors ${cat === c.id ? "bg-violet-500/30 text-white" : "bg-white/5 text-slate-400 hover:text-slate-200"}`}>
                  {c.label}
                </button>
              ))}
            </div>
            <Button size="sm" onClick={() => setComposing((v) => !v)} className="bg-violet-500 hover:bg-violet-400"><Plus className="mr-1.5 h-4 w-4" /> Share</Button>
          </div>

          {composing && (
            <GlowCard className="p-5">
              <SectionLabel>New war story</SectionLabel>
              <Input className="mt-3" placeholder="Headline" value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} />
              <Textarea rows={3} className="mt-2" placeholder="What happened, and what it took…" value={draft.body} onChange={(e) => setDraft({ ...draft, body: e.target.value })} />
              <div className="mt-3 flex flex-wrap items-center gap-2">
                <select value={draft.cat} onChange={(e) => setDraft({ ...draft, cat: e.target.value })} className="h-9 rounded-md border border-white/10 bg-white/[0.03] px-3 text-sm text-white">
                  {CATEGORIES.filter((c) => c.id !== "all").map((c) => <option key={c.id} value={c.id} className="bg-slate-900">{c.label}</option>)}
                </select>
                <button onClick={() => setDraft({ ...draft, anon: !draft.anon })} className={`flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs ${draft.anon ? "bg-violet-500/30 text-violet-100" : "bg-white/5 text-slate-400"}`}>
                  <EyeOff className="h-3.5 w-3.5" /> {draft.anon ? "Anonymous" : "Named"}
                </button>
                <Button size="sm" onClick={post} className="ml-auto bg-violet-500 hover:bg-violet-400">Post</Button>
              </div>
            </GlowCard>
          )}

          {visible.map((s) => (
            <GlowCard key={s.id} className="p-5">
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-sm text-slate-300">
                  {s.anon ? <EyeOff className="h-3.5 w-3.5 text-slate-500" /> : <Users className="h-3.5 w-3.5 text-violet-300" />}
                  {s.author}
                </span>
                <Badge variant="outline" style={{ borderColor: `${CAT_COLOR[s.cat]}55`, color: CAT_COLOR[s.cat] }}>
                  {CATEGORIES.find((c) => c.id === s.cat)?.label}
                </Badge>
              </div>
              <h3 className="mt-2 text-base font-semibold text-white">{s.title}</h3>
              <p className="mt-1 text-sm text-slate-400">{s.body}</p>
              <div className="mt-4 flex items-center gap-5 text-xs text-slate-500">
                <button onClick={() => like(s.id)} className={`flex items-center gap-1.5 transition-colors ${s.liked ? "text-rose-400" : "hover:text-rose-300"}`}>
                  <Heart className={`h-4 w-4 ${s.liked ? "fill-rose-400" : ""}`} /> {s.likes}
                </button>
                <span className="flex items-center gap-1.5"><Eye className="h-4 w-4" /> {s.views}</span>
                {s.dollarImpact > 0 && <span className="ml-auto font-semibold text-emerald-300">{fmt$(s.dollarImpact)} impact</span>}
              </div>
            </GlowCard>
          ))}
        </div>

        {/* Leaderboard */}
        <div className="space-y-6 lg:sticky lg:top-4 lg:self-start">
          <GlowCard className="p-6">
            <SectionLabel icon={Trophy}>XP leaderboard</SectionLabel>
            <ul className="mt-4 space-y-2">
              {LEADERS.map((l, i) => (
                <li key={l.name} className={`flex items-center gap-3 rounded-xl border p-3 ${l.me ? "border-violet-400/50 bg-violet-500/10" : "border-white/8 bg-white/[0.02]"}`}>
                  <span className="w-5 text-sm font-semibold text-slate-500">{i + 1}</span>
                  <div className="min-w-0 flex-1">
                    <p className="flex items-center gap-1.5 text-sm font-medium text-white">
                      {l.tier === "crown" && <Crown className="h-3.5 w-3.5 text-amber-300" />}
                      {l.tier === "blackeye" && <Eye className="h-3.5 w-3.5 text-rose-400" />}
                      {l.name}
                    </p>
                    <p className="text-[11px] text-slate-500">Rep {l.rep} · {l.xp.toLocaleString()} XP</p>
                  </div>
                </li>
              ))}
            </ul>
            <p className="mt-3 text-[11px] text-slate-500">Crown above 75 · black eye below 50. Standing reflects matched word and action.</p>
          </GlowCard>

          <GlowCard className="p-6">
            <SectionLabel icon={Users}>The covenant</SectionLabel>
            <p className="mt-2 text-sm leading-relaxed text-slate-300">
              Privacy first. Share the strategy and the struggle, never a client's identity. Every story
              here is proof a physician chose power, love, and a sound mind over fear.
            </p>
          </GlowCard>
        </div>
      </div>
    </AppShell>
  );
}

import { AppShell } from "@/components/AppShell";
import { SECONDARY_CATALOG, SECONDARY_CATEGORIES, type SecondaryCatalogCategory } from "@/lib/secondaryCatalog";
import { Archive, ArrowUpRight, BookOpen, Filter, Search, ShieldCheck } from "lucide-react";
import { useMemo, useState } from "react";
import { Link } from "wouter";

const categoryDescription: Record<SecondaryCatalogCategory, string> = {
  "Advanced Analysis": "Specialized calculators, comparisons, simulators, and analytical workbenches.",
  "Reports & Documents": "Report builders, presentations, documents, statements, and export-oriented tools.",
  "Reference & Education": "Libraries, training, timelines, tutorials, video, and reference material.",
  "Operations & Administration": "Administrative, monitoring, integration, workspace, and operational utilities.",
  "Experience & Experimental": "Experiential, gamified, community, and exploratory interfaces outside core planning workflows.",
  "Additional Tools": "Useful specialist pages that are preserved but are not part of the primary advisor path.",
};

export default function SecondaryInformation() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<SecondaryCatalogCategory | "All">("All");

  const filtered = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    return SECONDARY_CATALOG.filter(item => {
      const matchesCategory = category === "All" || item.category === category;
      const matchesQuery = !normalized || item.label.toLowerCase().includes(normalized) || item.path.toLowerCase().includes(normalized);
      return matchesCategory && matchesQuery;
    });
  }, [category, query]);

  const grouped = useMemo(() => SECONDARY_CATEGORIES.map(name => ({
    name,
    items: filtered.filter(item => item.category === name),
  })).filter(group => group.items.length > 0), [filtered]);

  return (
    <AppShell subtitle="Preserved specialist tools, reference material, and non-primary workflows">
      <div className="mx-auto max-w-7xl space-y-6 px-4 py-6 sm:px-6 lg:px-8">
        <section className="relative overflow-hidden rounded-3xl border border-violet-400/20 bg-[radial-gradient(circle_at_15%_0%,rgba(124,58,237,.24),transparent_34%),linear-gradient(145deg,rgba(15,10,28,.98),rgba(7,10,18,.98))] p-6 shadow-[0_28px_90px_rgba(45,20,90,.24)] sm:p-8">
          <div className="absolute right-0 top-0 h-48 w-48 rounded-full bg-violet-500/10 blur-3xl" />
          <div className="relative grid gap-8 lg:grid-cols-[1fr_auto] lg:items-end">
            <div>
              <div className="mb-4 flex h-11 w-11 items-center justify-center rounded-2xl border border-violet-300/25 bg-violet-500/15">
                <Archive className="h-5 w-5 text-violet-300" />
              </div>
              <p className="text-xs font-semibold uppercase tracking-[0.24em] text-violet-300">Secondary Information</p>
              <h1 className="mt-2 text-3xl font-semibold tracking-tight text-white sm:text-4xl">Everything preserved, without crowding the core workflow.</h1>
              <p className="mt-4 max-w-3xl text-sm leading-7 text-violet-100/60 sm:text-base">These pages remain fully routed and searchable. They are separated from the primary advisor path because they are specialist, reference-oriented, administrative, duplicative, or still awaiting the usefulness audit. No page has been deleted.</p>
            </div>
            <div className="grid min-w-44 grid-cols-2 gap-3">
              <div className="rounded-2xl border border-white/10 bg-black/25 p-4">
                <div className="text-2xl font-semibold text-white">{SECONDARY_CATALOG.length}</div>
                <div className="mt-1 text-xs text-violet-100/50">preserved pages</div>
              </div>
              <div className="rounded-2xl border border-white/10 bg-black/25 p-4">
                <div className="text-2xl font-semibold text-white">{SECONDARY_CATEGORIES.length}</div>
                <div className="mt-1 text-xs text-violet-100/50">clear groups</div>
              </div>
            </div>
          </div>
        </section>

        <section className="rounded-2xl border border-violet-400/15 bg-[#0a0812]/95 p-4 shadow-xl shadow-black/20 sm:p-5">
          <div className="grid gap-3 lg:grid-cols-[1fr_auto]">
            <label className="relative block">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-violet-300/70" />
              <input
                value={query}
                onChange={event => setQuery(event.target.value)}
                placeholder="Search every secondary page…"
                className="h-11 w-full rounded-xl border border-violet-400/20 bg-black/30 pl-10 pr-4 text-sm text-white outline-none transition placeholder:text-violet-100/35 focus:border-violet-400/60 focus:ring-2 focus:ring-violet-500/15"
              />
            </label>
            <div className="flex items-center gap-2 overflow-x-auto pb-1 lg:max-w-3xl">
              <Filter className="h-4 w-4 shrink-0 text-violet-300/60" />
              {(["All", ...SECONDARY_CATEGORIES] as const).map(value => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setCategory(value)}
                  className={`shrink-0 rounded-full border px-3 py-2 text-xs font-semibold transition active:scale-[0.97] ${category === value ? "border-violet-400/50 bg-violet-500/20 text-violet-100" : "border-white/10 bg-white/[0.03] text-violet-100/50 hover:border-violet-400/30 hover:text-violet-100"}`}
                >
                  {value}
                </button>
              ))}
            </div>
          </div>
        </section>

        {grouped.length === 0 ? (
          <section className="grid min-h-56 place-items-center rounded-2xl border border-dashed border-violet-400/20 bg-white/[0.02] text-center">
            <div><BookOpen className="mx-auto h-8 w-8 text-violet-300/45" /><p className="mt-3 font-medium text-white">No secondary pages match this search.</p><p className="mt-1 text-sm text-violet-100/45">Try another term or select All.</p></div>
          </section>
        ) : (
          grouped.map(group => (
            <section key={group.name} className="rounded-2xl border border-white/8 bg-[#0a0812]/80 p-5 sm:p-6">
              <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
                <div><h2 className="text-lg font-semibold text-white">{group.name}</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-violet-100/45">{categoryDescription[group.name]}</p></div>
                <span className="rounded-full border border-violet-400/15 bg-violet-500/10 px-3 py-1 text-xs font-semibold text-violet-200">{group.items.length} pages</span>
              </div>
              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
                {group.items.map(item => (
                  <Link key={item.path} href={item.path} className="group flex min-h-24 items-start justify-between gap-4 rounded-xl border border-white/8 bg-white/[0.025] p-4 transition duration-200 hover:-translate-y-0.5 hover:border-violet-400/30 hover:bg-violet-500/[0.06]">
                    <div className="min-w-0"><div className="font-medium text-violet-50 group-hover:text-white">{item.label}</div><div className="mt-2 truncate font-mono text-[10px] text-violet-100/30">{item.path}</div></div>
                    <ArrowUpRight className="h-4 w-4 shrink-0 text-violet-300/35 transition group-hover:text-violet-300" />
                  </Link>
                ))}
              </div>
            </section>
          ))
        )}

        <section className="flex items-start gap-3 rounded-2xl border border-emerald-400/15 bg-emerald-500/[0.04] p-5 text-sm leading-6 text-emerald-50/65">
          <ShieldCheck className="mt-0.5 h-5 w-5 shrink-0 text-emerald-300" />
          <p>The page audit will assign every route a usefulness score and recommendation. Items may later move between the primary workflow and this library, but no route will be removed without an explicit owner decision.</p>
        </section>
      </div>
    </AppShell>
  );
}

import { AppShell } from "@/components/AppShell";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import {
  Archive,
  CheckCircle2,
  CircleAlert,
  ClipboardList,
  FilePlus2,
  Loader2,
  MessageSquarePlus,
  RefreshCw,
  Save,
  Users,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

const WORKFLOW_STAGES = ["discovery", "analysis", "strategy", "review", "implementation", "complete"] as const;
const STATUS_LABELS = {
  draft: "Draft",
  active: "Active",
  review: "In review",
  completed: "Completed",
  archived: "Archived",
} as const;

function formatDate(value: Date | string | null | undefined) {
  if (!value) return "Not saved";
  return new Date(value).toLocaleString();
}

export default function PlanningCases() {
  const utils = trpc.useUtils();
  const casesQuery = trpc.planningCases.list.useQuery();
  const clientsQuery = trpc.clients.list.useQuery();
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newClientId, setNewClientId] = useState("");
  const [title, setTitle] = useState("");
  const [status, setStatus] = useState<keyof typeof STATUS_LABELS>("draft");
  const [stage, setStage] = useState<(typeof WORKFLOW_STAGES)[number]>("discovery");
  const [objectives, setObjectives] = useState("");
  const [riskNotes, setRiskNotes] = useState("");
  const [resultSummary, setResultSummary] = useState("");
  const [note, setNote] = useState("");

  const cases = casesQuery.data ?? [];
  const clients = clientsQuery.data ?? [];
  const selectedCase = trpc.planningCases.get.useQuery(
    { id: selectedId ?? 0 },
    { enabled: selectedId !== null },
  );
  const notesQuery = trpc.planningCases.notes.useQuery(
    { planningCaseId: selectedId ?? 0 },
    { enabled: selectedId !== null },
  );

  useEffect(() => {
    if (!selectedId && cases.length > 0) setSelectedId(cases[0].id);
  }, [cases, selectedId]);

  useEffect(() => {
    const item = selectedCase.data;
    if (!item) return;
    const assumptions = (item.assumptions ?? {}) as Record<string, unknown>;
    const results = (item.results ?? {}) as Record<string, unknown>;
    setTitle(item.title);
    setStatus(item.status);
    setStage(item.currentStage as (typeof WORKFLOW_STAGES)[number]);
    setObjectives(typeof assumptions.objectives === "string" ? assumptions.objectives : "");
    setRiskNotes(typeof assumptions.riskNotes === "string" ? assumptions.riskNotes : "");
    setResultSummary(typeof results.summary === "string" ? results.summary : "");
  }, [selectedCase.data]);

  const clientNameById = useMemo(
    () => new Map(clients.map(client => [client.id, client.name])),
    [clients],
  );

  const createCase = trpc.planningCases.create.useMutation({
    onSuccess: async created => {
      await utils.planningCases.list.invalidate();
      if (created?.id) setSelectedId(created.id);
      setNewTitle("");
      setNewClientId("");
      setShowCreate(false);
      toast.success("Planning case created");
    },
    onError: error => toast.error(error.message),
  });

  const updateCase = trpc.planningCases.update.useMutation({
    onSuccess: async () => {
      await Promise.all([
        utils.planningCases.list.invalidate(),
        selectedId ? utils.planningCases.get.invalidate({ id: selectedId }) : Promise.resolve(),
      ]);
      toast.success("Planning case saved");
    },
    onError: error => toast.error(error.message),
  });

  const addNote = trpc.planningCases.addNote.useMutation({
    onSuccess: async () => {
      if (selectedId) await utils.planningCases.notes.invalidate({ planningCaseId: selectedId });
      setNote("");
      toast.success("Note saved");
    },
    onError: error => toast.error(error.message),
  });

  const saveCurrent = () => {
    if (!selectedId) return;
    updateCase.mutate({
      id: selectedId,
      title,
      status,
      currentStage: stage,
      assumptions: { objectives, riskNotes },
      results: { summary: resultSummary },
      workflowState: {
        completedSteps: WORKFLOW_STAGES.slice(0, Math.max(0, WORKFLOW_STAGES.indexOf(stage))),
        activeStage: stage,
      },
    });
  };

  return (
    <AppShell title="Planning Cases" subtitle="Persistent client planning workflows">
      <div className="mx-auto max-w-[1500px] space-y-6 p-4 md:p-7">
        <section className="overflow-hidden rounded-3xl border border-violet-400/20 bg-gradient-to-br from-violet-950/80 via-slate-950/90 to-fuchsia-950/55 p-6 shadow-2xl shadow-violet-950/40">
          <div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
            <div className="max-w-3xl">
              <div className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.22em] text-violet-300">
                <ClipboardList className="h-4 w-4" /> Durable planning workspace
              </div>
              <h1 className="text-3xl font-semibold tracking-tight text-white md:text-4xl">Every recommendation has a saved case.</h1>
              <p className="mt-3 max-w-2xl text-sm leading-6 text-slate-300">
                Link planning work to a real client, retain assumptions and results, record advisor notes, and advance the workflow without losing context between sessions.
              </p>
            </div>
            <Button onClick={() => setShowCreate(value => !value)} className="bg-violet-500 text-white hover:bg-violet-400">
              <FilePlus2 className="mr-2 h-4 w-4" /> New planning case
            </Button>
          </div>
        </section>

        {showCreate && (
          <section className="rounded-2xl border border-violet-400/20 bg-slate-950/75 p-5 shadow-xl">
            <div className="grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end">
              <label className="space-y-2 text-sm text-slate-300">
                <span>Case title</span>
                <Input value={newTitle} onChange={event => setNewTitle(event.target.value)} placeholder="Morgan household retirement plan" />
              </label>
              <label className="space-y-2 text-sm text-slate-300">
                <span>Linked client</span>
                <select value={newClientId} onChange={event => setNewClientId(event.target.value)} className="h-10 w-full rounded-md border border-violet-400/20 bg-slate-950 px-3 text-sm text-white">
                  <option value="">No client selected</option>
                  {clients.map(client => <option key={client.id} value={client.id}>{client.name}</option>)}
                </select>
              </label>
              <Button
                disabled={newTitle.trim().length < 2 || createCase.isPending}
                onClick={() => createCase.mutate({ title: newTitle.trim(), clientId: newClientId ? Number(newClientId) : null, caseType: "comprehensive" })}
              >
                {createCase.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <FilePlus2 className="mr-2 h-4 w-4" />}
                Create
              </Button>
            </div>
          </section>
        )}

        <div className="grid gap-6 xl:grid-cols-[340px_minmax(0,1fr)]">
          <aside className="rounded-2xl border border-violet-400/15 bg-slate-950/70 p-3 shadow-xl">
            <div className="flex items-center justify-between px-2 py-2">
              <div>
                <p className="text-sm font-semibold text-white">Planning cases</p>
                <p className="text-xs text-slate-400">{cases.length} saved workflow{cases.length === 1 ? "" : "s"}</p>
              </div>
              <Button variant="ghost" size="icon" onClick={() => casesQuery.refetch()} aria-label="Refresh planning cases">
                <RefreshCw className={`h-4 w-4 ${casesQuery.isFetching ? "animate-spin" : ""}`} />
              </Button>
            </div>

            {casesQuery.isLoading ? (
              <div className="flex items-center justify-center py-16 text-violet-300"><Loader2 className="h-6 w-6 animate-spin" /></div>
            ) : casesQuery.isError ? (
              <div className="m-2 rounded-xl border border-red-400/20 bg-red-950/30 p-4 text-sm text-red-200">
                <CircleAlert className="mb-2 h-5 w-5" /> {casesQuery.error.message}
              </div>
            ) : cases.length === 0 ? (
              <div className="m-2 rounded-xl border border-dashed border-violet-400/25 p-6 text-center">
                <ClipboardList className="mx-auto mb-3 h-8 w-8 text-violet-300" />
                <p className="text-sm font-medium text-white">No planning cases yet</p>
                <p className="mt-1 text-xs leading-5 text-slate-400">Create the first case to persist assumptions, results, and advisor notes.</p>
              </div>
            ) : (
              <div className="space-y-2">
                {cases.map(item => (
                  <button
                    key={item.id}
                    onClick={() => setSelectedId(item.id)}
                    className={`w-full rounded-xl border p-4 text-left transition ${selectedId === item.id ? "border-violet-400/45 bg-violet-500/15" : "border-transparent bg-white/[0.03] hover:border-violet-400/20 hover:bg-violet-500/10"}`}
                  >
                    <div className="flex items-start justify-between gap-3">
                      <p className="line-clamp-2 text-sm font-semibold text-white">{item.title}</p>
                      {item.status === "archived" && <Archive className="h-4 w-4 shrink-0 text-slate-500" />}
                    </div>
                    <p className="mt-2 text-xs text-violet-200">{clientNameById.get(item.clientId ?? -1) ?? "Unlinked case"}</p>
                    <div className="mt-3 flex items-center justify-between text-[11px] text-slate-500">
                      <span className="capitalize">{item.currentStage}</span>
                      <span>{formatDate(item.lastSavedAt)}</span>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </aside>

          <main className="min-w-0">
            {!selectedId ? (
              <div className="flex min-h-[520px] items-center justify-center rounded-2xl border border-dashed border-violet-400/25 bg-slate-950/50 p-10 text-center">
                <div><Users className="mx-auto mb-4 h-10 w-10 text-violet-300" /><p className="font-medium text-white">Select or create a planning case</p></div>
              </div>
            ) : selectedCase.isLoading ? (
              <div className="flex min-h-[520px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-violet-300" /></div>
            ) : selectedCase.isError ? (
              <div className="rounded-2xl border border-red-400/20 bg-red-950/30 p-6 text-red-200">{selectedCase.error.message}</div>
            ) : (
              <div className="space-y-5">
                <section className="rounded-2xl border border-violet-400/15 bg-slate-950/70 p-5 shadow-xl">
                  <div className="grid gap-4 lg:grid-cols-[1fr_180px_180px_auto] lg:items-end">
                    <label className="space-y-2 text-sm text-slate-300"><span>Case title</span><Input value={title} onChange={event => setTitle(event.target.value)} /></label>
                    <label className="space-y-2 text-sm text-slate-300"><span>Status</span><select value={status} onChange={event => setStatus(event.target.value as keyof typeof STATUS_LABELS)} className="h-10 w-full rounded-md border border-violet-400/20 bg-slate-950 px-3 text-sm text-white">{Object.entries(STATUS_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
                    <label className="space-y-2 text-sm text-slate-300"><span>Current stage</span><select value={stage} onChange={event => setStage(event.target.value as (typeof WORKFLOW_STAGES)[number])} className="h-10 w-full rounded-md border border-violet-400/20 bg-slate-950 px-3 text-sm capitalize text-white">{WORKFLOW_STAGES.map(value => <option key={value} value={value}>{value}</option>)}</select></label>
                    <Button onClick={saveCurrent} disabled={updateCase.isPending}><Save className="mr-2 h-4 w-4" />{updateCase.isPending ? "Saving" : "Save case"}</Button>
                  </div>
                  <div className="mt-5 grid grid-cols-3 gap-2 sm:grid-cols-6">
                    {WORKFLOW_STAGES.map((value, index) => {
                      const activeIndex = WORKFLOW_STAGES.indexOf(stage);
                      const complete = index < activeIndex;
                      const active = value === stage;
                      return <button key={value} onClick={() => setStage(value)} className={`rounded-xl border px-2 py-3 text-center text-[11px] font-medium capitalize ${active ? "border-violet-300/60 bg-violet-500/25 text-white" : complete ? "border-emerald-400/20 bg-emerald-500/10 text-emerald-200" : "border-white/10 bg-white/[0.02] text-slate-500"}`}>{complete && <CheckCircle2 className="mx-auto mb-1 h-4 w-4" />}{value}</button>;
                    })}
                  </div>
                </section>

                <div className="grid gap-5 lg:grid-cols-2">
                  <section className="rounded-2xl border border-violet-400/15 bg-slate-950/70 p-5 shadow-xl">
                    <h2 className="font-semibold text-white">Discovery assumptions</h2>
                    <p className="mt-1 text-xs text-slate-400">Saved with this case—not held only in the browser.</p>
                    <label className="mt-5 block space-y-2 text-sm text-slate-300"><span>Objectives and priorities</span><Textarea value={objectives} onChange={event => setObjectives(event.target.value)} rows={6} placeholder="Retirement timing, liquidity needs, estate priorities…" /></label>
                    <label className="mt-4 block space-y-2 text-sm text-slate-300"><span>Risk and constraints</span><Textarea value={riskNotes} onChange={event => setRiskNotes(event.target.value)} rows={4} placeholder="Risk tolerance, tax constraints, compliance concerns…" /></label>
                  </section>
                  <section className="rounded-2xl border border-violet-400/15 bg-slate-950/70 p-5 shadow-xl">
                    <h2 className="font-semibold text-white">Recommendation summary</h2>
                    <p className="mt-1 text-xs text-slate-400">Capture the current conclusion while calculators and reports retain their own detailed records.</p>
                    <Textarea className="mt-5" value={resultSummary} onChange={event => setResultSummary(event.target.value)} rows={12} placeholder="Summarize the recommended strategy, evidence, tradeoffs, and next decision…" />
                  </section>
                </div>

                <section className="rounded-2xl border border-violet-400/15 bg-slate-950/70 p-5 shadow-xl">
                  <div className="flex items-center justify-between gap-4"><div><h2 className="font-semibold text-white">Case notes</h2><p className="mt-1 text-xs text-slate-400">Advisor, client, compliance, and system notes are timestamped and persisted.</p></div><MessageSquarePlus className="h-5 w-5 text-violet-300" /></div>
                  <div className="mt-5 flex flex-col gap-3 sm:flex-row"><Textarea value={note} onChange={event => setNote(event.target.value)} rows={3} placeholder="Add a decision, follow-up, or compliance note…" /><Button className="sm:self-end" disabled={!note.trim() || addNote.isPending} onClick={() => addNote.mutate({ planningCaseId: selectedId, noteType: "advisor", content: note.trim() })}>{addNote.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <MessageSquarePlus className="mr-2 h-4 w-4" />}Save note</Button></div>
                  <div className="mt-5 space-y-3">
                    {notesQuery.isLoading ? <Loader2 className="h-5 w-5 animate-spin text-violet-300" /> : (notesQuery.data ?? []).length === 0 ? <p className="rounded-xl border border-dashed border-white/10 p-5 text-sm text-slate-500">No notes have been added.</p> : (notesQuery.data ?? []).map(item => <article key={item.id} className="rounded-xl border border-white/10 bg-white/[0.03] p-4"><div className="flex items-center justify-between gap-3"><span className="text-xs font-semibold uppercase tracking-wider text-violet-300">{item.noteType}</span><span className="text-xs text-slate-500">{formatDate(item.createdAt)}</span></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-200">{item.content}</p></article>)}
                  </div>
                </section>
              </div>
            )}
          </main>
        </div>
      </div>
    </AppShell>
  );
}

import { AppShell } from "@/components/AppShell";
import { Button } from "@/components/ui/button";
import { PAGE_AUDIT_SUMMARY } from "@/data/pageAuditSummary";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { Activity, AlertTriangle, CheckCircle2, FileSearch, RefreshCw, ShieldCheck, Users } from "lucide-react";

function MetricCard({ label, value, detail, tone = "violet" }: { label: string; value: string | number; detail: string; tone?: "violet" | "emerald" | "amber" | "red" }) {
  const tones = {
    violet: "border-violet-400/20 bg-violet-950/25 text-violet-200",
    emerald: "border-emerald-400/20 bg-emerald-950/20 text-emerald-200",
    amber: "border-amber-400/20 bg-amber-950/20 text-amber-200",
    red: "border-red-400/20 bg-red-950/20 text-red-200",
  };
  return <div className={`rounded-2xl border p-5 ${tones[tone]}`}><p className="text-xs uppercase tracking-[0.18em] opacity-70">{label}</p><p className="mt-2 text-3xl font-semibold text-white">{value}</p><p className="mt-2 text-xs opacity-70">{detail}</p></div>;
}

export default function SystemHealth() {
  const { user } = useAuth();
  const enabled = user?.role === "admin";
  const errorStats = trpc.errorLog.stats.useQuery(undefined, { enabled, retry: false });
  const recentErrors = trpc.errorLog.list.useQuery({ limit: 20, offset: 0 }, { enabled, retry: false });
  const usage = trpc.ownerAnalytics.summary.useQuery(undefined, { enabled, retry: false });
  const topPages = trpc.ownerAnalytics.topPages.useQuery({ limit: 10 }, { enabled, retry: false });
  const queries = [errorStats, recentErrors, usage, topPages];
  const loading = enabled && queries.some(query => query.isLoading);
  const failures = queries.filter(query => query.isError);

  const retryAll = () => Promise.all(queries.map(query => query.refetch()));

  if (!enabled) {
    return <AppShell title="System Health" subtitle="Administrative telemetry and release readiness"><div className="rounded-2xl border border-amber-400/25 bg-amber-950/25 p-8"><div className="flex items-center gap-3 text-amber-200"><ShieldCheck className="h-6 w-6" /><h2 className="text-xl font-semibold">Administrator access required</h2></div><p className="mt-3 max-w-2xl text-sm text-amber-100/70">Managed OAuth roles protect error records, usage analytics, and release-audit details. No secondary password or client-side bypass is accepted.</p></div></AppShell>;
  }

  return (
    <AppShell title="System Health" subtitle="Route readiness, persisted failures, and actual portal usage">
      <div className="space-y-6">
        {failures.length > 0 && <div className="flex flex-col gap-3 rounded-2xl border border-red-400/25 bg-red-950/30 p-4 text-red-100 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0" /><div><p className="font-semibold">Some health data could not be loaded.</p><p className="mt-1 text-xs text-red-200/70">{failures.map(query => query.error?.message).filter(Boolean).join(" · ")}</p></div></div><Button variant="outline" onClick={retryAll}><RefreshCw className="mr-2 h-4 w-4" />Retry</Button></div>}

        {loading && <div className="flex items-center gap-3 rounded-2xl border border-violet-400/20 bg-violet-950/20 p-4 text-sm text-violet-100"><RefreshCw className="h-4 w-4 animate-spin" />Loading persisted health telemetry…</div>}

        <section>
          <div className="mb-3 flex items-center gap-2"><FileSearch className="h-5 w-5 text-violet-300" /><h2 className="text-lg font-semibold text-white">Page audit</h2></div>
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <MetricCard label="Audited routes" value={PAGE_AUDIT_SUMMARY.routeCount} detail="Every explicit route scored; no pages deleted" />
            <MetricCard label="Average usefulness" value={`${PAGE_AUDIT_SUMMARY.averageScore}/10`} detail={`${PAGE_AUDIT_SUMMARY.fiveOrHigherCount} pages score five or higher`} tone="emerald" />
            <MetricCard label="Source-level healthy" value={PAGE_AUDIT_SUMMARY.renderHealth.healthy} detail={`${PAGE_AUDIT_SUMMARY.renderHealth.atRisk} at risk; runtime checks remain separate`} tone="emerald" />
            <MetricCard label="Below five" value={PAGE_AUDIT_SUMMARY.belowFiveCount} detail="Merge, secondary-library, improvement, or owner-approved retirement candidates" tone="amber" />
          </div>
        </section>

        <section>
          <div className="mb-3 flex items-center gap-2"><Activity className="h-5 w-5 text-violet-300" /><h2 className="text-lg font-semibold text-white">Runtime health</h2></div>
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <MetricCard label="Errors, 24 hours" value={errorStats.data?.last24h ?? "—"} detail="Persisted page and application errors" tone={(errorStats.data?.last24h ?? 0) > 0 ? "red" : "emerald"} />
            <MetricCard label="Errors, 7 days" value={errorStats.data?.last7d ?? "—"} detail={`${errorStats.data?.total ?? 0} total retained records`} tone={(errorStats.data?.last7d ?? 0) > 0 ? "amber" : "emerald"} />
            <MetricCard label="Tracked sessions" value={usage.data?.totalSessions ?? "—"} detail={`${usage.data?.activeSessions ?? 0} active sessions`} />
            <MetricCard label="Observed users" value={usage.data?.totalAdvisors ?? usage.data?.totalUsers ?? "—"} detail={`${usage.data?.loginsLast24h ?? 0} logins in the last 24 hours`} />
          </div>
        </section>

        <div className="grid gap-6 xl:grid-cols-2">
          <section className="rounded-2xl border border-violet-400/15 bg-slate-950/45 p-5">
            <div className="mb-4 flex items-center gap-2"><Users className="h-5 w-5 text-violet-300" /><h2 className="font-semibold text-white">Most-used pages</h2></div>
            {topPages.data?.length ? <div className="space-y-3">{topPages.data.map((page: any) => <div key={`${page.pagePath}-${page.pageTitle}`} className="flex items-center justify-between gap-4 rounded-xl border border-white/5 bg-white/[0.025] px-4 py-3"><div className="min-w-0"><p className="truncate text-sm font-medium text-slate-100">{page.pageTitle || page.pagePath}</p><p className="truncate text-xs text-slate-500">{page.pagePath}</p></div><div className="text-right"><p className="text-sm font-semibold text-violet-200">{Number(page.visits).toLocaleString()}</p><p className="text-[10px] uppercase tracking-wide text-slate-500">visits</p></div></div>)}</div> : !topPages.isLoading && <p className="text-sm text-slate-400">No page visits have been recorded yet.</p>}
          </section>

          <section className="rounded-2xl border border-violet-400/15 bg-slate-950/45 p-5">
            <div className="mb-4 flex items-center gap-2"><AlertTriangle className="h-5 w-5 text-violet-300" /><h2 className="font-semibold text-white">Recent errors</h2></div>
            {recentErrors.data?.length ? <div className="space-y-3">{recentErrors.data.map(error => <div key={error.id} className="rounded-xl border border-white/5 bg-white/[0.025] px-4 py-3"><div className="flex items-center justify-between gap-4"><p className="truncate text-sm font-medium text-slate-100">{error.message}</p><span className="shrink-0 text-[10px] uppercase tracking-wide text-red-300">{error.level}</span></div><p className="mt-1 truncate text-xs text-slate-500">{error.url || error.source}</p><p className="mt-1 text-[10px] text-slate-600">{new Date(error.createdAt).toLocaleString()}</p></div>)}</div> : !recentErrors.isLoading && <div className="flex items-center gap-2 text-sm text-emerald-200"><CheckCircle2 className="h-4 w-4" />No persisted errors have been recorded.</div>}
          </section>
        </div>
      </div>
    </AppShell>
  );
}
